import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

function getValidMetricIds(evaluations) {
  return evaluations.map((metric) => metric.id);
}

export function validateThresholds({ thresholds, evaluations }) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return null;
  }

  const validMetricIds = getValidMetricIds(evaluations);
  const errors = [];

  for (const [metricId, minScore] of Object.entries(thresholds)) {
    if (!validMetricIds.includes(metricId)) {
      errors.push(
        `Unknown metric '${metricId}'. Valid metrics are: ${validMetricIds.join(', ')}`
      );
      continue;
    }
    if (typeof minScore !== 'number') {
      errors.push(`Threshold for '${metricId}' must be a number, got ${typeof minScore}`);
      continue;
    }
    if (minScore < 0 || minScore > 1) {
      errors.push(`Threshold for '${metricId}' must be between 0 and 1, got ${minScore}`);
    }
  }

  if (errors.length > 0) {
    return {
      valid: false,
      errors
    };
  }

  return { valid: true, errors: [] };
}

export function evaluateThresholds({ thresholds, evaluations }) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return {
      passed: true,
      thresholds: []
    };
  }

  const metricsById = Object.fromEntries(
    evaluations.map((metric) => [metric.id, metric])
  );

  const thresholdResults = [];
  let allPassed = true;

  for (const [metricId, min] of Object.entries(thresholds)) {
    const metric = metricsById[metricId];
    const score = metric?.score ?? null;
    const passed = score !== null && score >= min;

    if (!passed) {
      allPassed = false;
    }

    thresholdResults.push({
      metric: metricId,
      min,
      score,
      passed
    });
  }

  return {
    passed: allPassed,
    thresholds: thresholdResults
  };
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdValidation = validateThresholds({ thresholds, evaluations });
  if (thresholdValidation && !thresholdValidation.valid) {
    throw new Error(
      `Invalid thresholds: ${thresholdValidation.errors.join('; ')}`
    );
  }

  const thresholdEvaluation = evaluateThresholds({ thresholds, evaluations });

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdEvaluation.thresholds.length > 0) {
    report.passed = thresholdEvaluation.passed;
    report.thresholds = thresholdEvaluation.thresholds;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

