    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const result = evaluateThresholds({
      thresholds: { exact_match: 0.9, toxicity: 0.8 },
      evaluations
    });
    expect(result.passed).toBe(true);
    expect(result.thresholds).toHaveLength(2);
    expect(result.thresholds[0].metric).toBe('exact_match');
    expect(result.thresholds[0].passed).toBe(true);
  });

  it('marks thresholds as failed when score is below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const result = evaluateThresholds({
      thresholds: { exact_match: 0.99 },
      evaluations
    });
    expect(result.passed).toBe(false);
    expect(result.thresholds[0].passed).toBe(false);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: 0,
        matches: 0,
        details: 'No references'
      }
    ];
    const result = evaluateThresholds({
      thresholds: { exact_match: 0.5 },
      evaluations
    });
    expect(result.passed).toBe(false);
    expect(result.thresholds[0].passed).toBe(false);
    expect(result.thresholds[0].score).toBe(null);
  });

  it('includes thresholds in generated report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9 }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0].metric).toBe('exact_match');
  });

  it('throws error when threshold validation fails in generateReport', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { unknown_metric: 0.5 }
      });
    }).toThrow('Invalid thresholds');
  });
});

