function parseThresholds(thresholdStrings?: string[]) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return undefined;
  }

  const thresholds: Record<string, number> = {};
  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
    if (!match) {
      log.error(`Invalid threshold format: "${thresholdStr}". Expected <metric>=<number>`, {});
      process.exit(2);
    }

    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (Number.isNaN(value)) {
      log.error(`Invalid threshold value for "${metricId}": "${valueStr}" is not a number.`, {});
      process.exit(2);
    }

    if (value < 0 || value > 1) {
      log.error(
        `Invalid threshold value for "${metricId}": ${value} is outside the range [0, 1].`,
        {}
      );
      process.exit(2);
    }

    thresholds[metricId] = value;
  }

  return thresholds;
}

